<div class="pagehead"><h1><?=e($title)?></h1><form><input name="q" value="<?=e($q)?>" placeholder="جستجو در این بخش"><button>جستجو</button></form></div><p class="muted"><?=number_format($total)?> عنوان</p><div class="table"><div class="thead"><span># / نام کتاب</span><span>مؤلف</span><span>جلد</span><span>بازدید</span></div><?php foreach($rows as $i=>$b):?><a class="tr" href="/book?id=<?=$b['id']?>"><span><em><?=($page-1)*20+$i+1?></em> <?=e($b['title'])?></span><span><?=e($b['author']??'—')?></span><span><?=e($b['volumes'])?></span><span><?=number_format($b['views'])?></span></a><?php endforeach;?></div><div class="pagination"><?php for($i=1;$i<=$pages;$i++):?><a class="<?=($i==$page?'active':'')?>" href="?<?=http_build_query(array_filter(['q'=>$q,'page'=>$i]))?>"><?=$i?></a><?php endfor;?></div>
